"use strict";
(function ($) {
    "use strict";
    Gordic.Previews.register("sml:DokladyPreview", {
        canRender: (dto) => { return dto.ixp != null; },
        render: (div, dto) => {
            div.empty();
            var currentElement = $(div);
            Gordic.Previews.displayLinkButton(div, dto);
            var form = $("<div class='gform--view-mode'>").appendTo(currentElement)
                .gform("setup", { layoutDescriptor: "L1M1S1, breaks-300-400" });
            form.gformsection("create").gpidbar({ pid: dto.ixp }).
                gformsection("create").
                gformrow("addFieldsRow", "jres:33500645").gformtext(dto.ac, "bold"). //RC 33500645 : Evidenční číslo
                gformrow("addFieldsRow", "jres:33500644").gformtext(dto.ac_sml, "bold"). //RC 33500644 : Agendové číslo
                //TODO: KNIHA
                gformrow("addFieldsRow", "jres:33500647").gformtext(GetSmlStav(SetSmlStav(Number(dto.sml_stav), Number(dto.findoc?.num_pol), Number(dto.findoc?.num_pol_sch))), "bold"). //RC 33500647 : Stav
                gformrow("addFieldsRow", "Měna").gformtext(dto.mena_txt, "bold").
                gformrow("addFieldsRow", "Datum uzavření").gformtext(new Date(dto.dat_uzavreni).toLocaleDateString(), "bold").
                gformrow("addFieldsRow", "Datum ukončení platnosti").gformtext(new Date(dto.dat_platnost).toLocaleDateString(), "bold").
                gformrow("addFieldsRow", "Datum účinnosti").gformtext(new Date(dto.dat_ucinnost).toLocaleDateString(), "bold").
                gformrow("addFieldsRow", "Celková částka").gformtext(dto.c_mena, "bold").
                gformrow("addFieldsRow", "Rozpis CZK").gformtext(dto.c, "bold").
                gformrow("addFieldsRow", "Položky CZK").gformtext(dto.c_pol, "bold").
                gformrow("addFieldsRow", "jres:33500646").gformtext(dto.popis, "bold"). //RC 33500646 : Popis
                //gformrow("addFieldsRow", "jres:33500651").gformtext(dto.typ_ceny, "bold").  //RC 33500651 : Typ ceny
                gformrow("addFieldsRow", "jres:33500652").gformtext(dto.fin_od, "bold"). //RC 33500652 : Financování od
                gformrow("addFieldsRow", "jres:33500653").gformtext(dto.fin_do, "bold"). //RC 33500653 : Financování do
                gformrow("addFieldsRow", "Název externího subjektu").gformtext(dto.ixs_esu_txt, "bold").
                gformrow("addFieldsRow", "IČO externího subjektu").gformtext(dto.ico_esu, "bold");
            if (dto.rc_esu != null && dto.rc_esu.trim() != "")
                form.gformrow("addFieldsRow", "Externí subjekt").gformtext(dto.rc_esu.trim(), "bold");
            currentElement.resize().find(".gform-section").children("label").first().addClass("g-state-text g-state-error");
        },
    });
    function GetSmlStav(mp_stav) {
        if (mp_stav == 10)
            return "Návrh";
        else if (mp_stav == 20)
            return "Evidence";
        else if (mp_stav == 23)
            return "Evidence, schválený FP";
        else if (mp_stav == 30)
            return "Schváleno";
        else if (mp_stav == 50)
            return "Ukončeno";
        else if (mp_stav == 90)
            return "Storno";
        else
            return "";
    }
    function SetSmlStav(sml_stav_p, num_pol_p, num_pol_sch_p) {
        //!360.23 30.07.09 dynamické = vytvoření nového stavu
        let l_stav = sml_stav_p;
        if (sml_stav_p == 20 && num_pol_p > 0 && num_pol_p == num_pol_sch_p)
            l_stav = 23;
        return l_stav;
    }
})(jQuery);
//# sourceMappingURL=data:application/json;base64,